1. {"tool": "browser_run_code_unsafe", "args": {"id": "<PROJECT_ID>/<ISSUE_IID>", "code": "// Requires a same-origin GitLab page already loaded in the tab (session cookie + page CSRF token).
const pid = '<PROJECT_ID>', iid = '<ISSUE_IID>';
const csrf = document.querySelector('meta[name="csrf-token"]').content;
// 1. Identity guard: the issue must still carry the title this run typed.
const before = await fetch(`/api/v4/projects/${pid}/issues/${iid}`, {credentials:'same-origin'});
const issue = await before.json();
if (before.status !== 200 || issue.title !== '<ISSUE_TITLE>') throw new Error('identity guard failed: ' + before.status + ' ' + issue.title);
// 2. Permanent delete (API form of the issue page Delete action).
const del = await fetch(`/api/v4/projects/${pid}/issues/${iid}`, {method:'DELETE', credentials:'same-origin', headers:{'X-CSRF-Token': csrf}});
// expect 204
// 3. Confirm removal on API and web page, and that the open-issue count returned to its pre-action value.
const api404 = await fetch(`/api/v4/projects/${pid}/issues/${iid}`, {credentials:'same-origin'});
const web404 = await fetch('<ISSUE_WEB_PATH>', {credentials:'same-origin'});
const count = await fetch(`/api/v4/projects/${pid}/issues?state=opened&per_page=1`, {credentials:'same-origin'});
return {deleteStatus: del.status, apiStatus: api404.status, webStatus: web404.status, openAfterDelete: count.headers.get('X-Total')};"}}

